    'label' => 'Final-Mile & White-Glove',
    'pdf' => 'FAQs-Final-Mile-and-White-Glove.pdf',
    'items' => 
    array (
      0 => 
      array (
        'q' => 'What is white-glove transportation?',
        'a' => '<p>White-glove transportation is a specialized logistics service designed for shipments that require added care, coordination, and inside handling. At McCollister’s, this practice typically includes multi-person teams, inside pickup and delivery, careful placement, protective handling during transit, and debris removal once items are unpacked.</p><p>The goal is to ensure your products are not just dropped off, but delivered pristinely, safely, and with minimal disruption to your operations.</p>',
